Ниже приведен пример высокого уровня, как написать игру «Змейка» на C, которая будет плавной и будет использовать изображения для анимации всего уровня. Обратите внимание, что это не полноценный код, а только пример и идеи, которые помогут вам приступить к разработке.

1. Сначала вам необходимо выбрать графический движок, который позволяет вам создавать плавную анимацию и работать с изображениями. В C вы можете использовать библиотеку SDL (Simple DirectMedia Layer), которая предоставляет широкий спектр функций для работы с графикой, звуком и вводом/выводом.

2. Создайте файлы с изображениями для змейки, яблока и стен, используя графический редактор, такой как Adobe Photoshop или GIMP. Формат файлов должен быть поддерживаемым SDL, обычно это форматы BMP, PNG, или JPEG.

3. Далее, создайте структуры данных для хранения информации о змейке, яблоке и стене, чтобы иметь возможность работать с ними в коде. Ваша структура змейки, например, может содержать информацию о положении головы, длине тела и направлении движения.

```c
typedef struct {
    int x, y;
    int length;
    int direction; // 0 - up, 1 - right, 2 - down, 3 - left
} Snake;

typedef struct {
    int x, y;
} Apple;

typedef struct {
    int x, y;
} Wall;
```

4. Следующим шагом создайте функции для отрисовки змейки, яблока и стен, используя SDL. Ваша функция для отрисовки змейки, например, должна получать структуру змейки и использовать SDL для отрисовки всех частей тела змейки на экране.

```c
void draw_snake(Snake* snake) {
    // Loop through snake body and draw each part
    for (int I = 0; I < snake->length; i++) {
        SDL_Rect rect = {snake->body[i].x, snake->body[i].y, TILE_SIZE, TILE_SIZE};
        SDL_RenderCopy(renderer, snake_texture, NULL, &rect);
    }
}

void draw_apple(Apple* apple) {
    SDL_Rect rect = {apple->x, apple->y, TILE_SIZE, TILE_SIZE};
    SDL_RenderCopy(renderer, apple_texture, NULL, &rect);
}

void draw_walls(Wall* walls, int num_walls) {
    for (int I = 0; I < num_walls; i++) {
        SDL_Rect rect = {walls[i].x, walls[i].y, TILE_SIZE, TILE_SIZE};
        SDL_RenderCopy(renderer, wall_texture, NULL, &rect);
    }
}
```

5. Ваша игра будет состоять из цикла, в котором будет происходить обновление игрового состояния и отрисовка экрана. В цикле вы можете реализовать логику движения змейки, столкновения с яблоком, столкновения с стенами и т.д.

```c
int main(int argc, char* argv[]) {
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create window
    SDL_Window* window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    // Create renderer
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Load textures
    SDL_Surface* snake_surface = SDL_LoadBMP("snake.bmp");
    SDL_Surface* apple_surface = SDL_LoadBMP("apple.bmp");
    SDL_Surface* wall_surface = SDL_LoadBMP("wall.bmp");

    SDL_Texture* snake_texture = SDL_CreateTextureFromSurface(renderer, snake_surface);
    SDL_Texture* apple_texture = SDL_CreateTextureFromSurface(renderer, apple_surface);
    SDL_Texture* wall_texture = SDL_CreateTextureFromSurface(renderer, wall_surface);

    // Create game objects
    Snake snake = { {100, 100}, 3, 0 }; // Start position and length of snake
    Apple apple = { 300, 300 }; // Random position of apple
    Wall walls[4] = { {0, 0}, {WINDOW_WIDTH, 0}, {0, WINDOW_HEIGHT}, {WINDOW_WIDTH, WINDOW_HEIGHT} }; // Walls of game area

    bool running = true;

    while (running) {
        // Handle input events
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                running = false;
            }
        }

        // Update game state
        // ...

        // Clear screen
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);

        // Draw game objects
        draw_walls(walls, 4);
        draw_snake(&snake);
        draw_apple(&apple);

        // Update screen
        SDL_RenderPresent(renderer);
    }

    // Clean up
    SDL_DestroyTexture(snake_texture);
    SDL_DestroyTexture(apple_texture);
    SDL_DestroyTexture(wall_texture);

    SDL_FreeSurface(snake_surface);
    SDL_FreeSurface(apple_surface);
    SDL_FreeSurface(wall_surface);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
```

