Следующий код на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string word; // Слово для поиска
    std::cout << "Enter the word to search: ";
    std::getline(std::cin, word); // Считываем слово с пробелами

    std::string filename;
    std::cout << "Enter the file name: ";
    std::getline(std::cin, filename);

    std::ifstream file(filename); // Открываем файл на чтение
    if (!file.is_open()) { // Проверяем, что файл успешно открыт
        std::cerr << "Error: Cannot open file " << filename << std::endl;
        return 1;
    }

    std::string line;
    int count = 0; // Счетчик вхождений слова
    while (getline(file, line)) { // Читаем файл построчно
        size_t pos = 0; // Переменная для хранения индекса начала найденного слова
        while ((pos = line.find(word, pos)) != std::string::npos) { // Ищем слово в строке
            pos++; // Переходим на следующую позицию для следующего поиска
            count++; // Увеличиваем счетчик вхождений
        }
    }

    file.close(); // Закрываем файл

    std::cout << "The word \"" << word << "\" appears " << count << " times in " << filename << std::endl;

    return 0;
}
```

